import itertools

def count_pairs_with_common_friend(edges, n):
    # edges is a list of tuples (u, v) where u, v are 0-indexed
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    s = set()
    for u in range(n):
        for v in range(u + 1, n):
            # Check if they are not friends
            if v not in adj[u]:
                # Check if they have a common friend
                common_friends = adj[u].intersection(adj[v])
                if len(common_friends) > 0:
                    s.add((u, v))
    return len(s)

